begin
 if exists(select 1 from jsonb_array_elements(v_rows) d
  left join public.webbase_products p on p.sku=d->>'sku'
  where p.id is null or p.name is distinct from d->>'name') then
  raise exception 'Compatibility identity mismatch; no changes applied';
 end if;
 update public.webbase_products p
 set specs=coalesce(p.specs,'{}'::jsonb)||jsonb_build_object('_compatibility',d),updated_at=now()
 from jsonb_array_elements(v_rows) d
 where p.sku=d->>'sku' and not (coalesce(p.specs,'{}'::jsonb) ? '_compatibility');
end $compatibility$;
select count(*) filter(where specs ? '_compatibility') reviewed_accessories,
 count(*) filter(where specs->'_compatibility'->>'kind'='vacuum') reviewed_vacuum_consumables
from public.webbase_products where active;
commit;
